+	Saver:      { url: "/framework/ext/Saver/",       icon: "save" },
+	Editor:     { url: "/framework/ext/editor/",      icon: "design_services" },
+	Timeline:   { url: "/framework/ext/Timeline/",    icon: "view_timeline" },
+	Drawer:     { url: "/framework/ext/drawer/",      icon: "view_sidebar" },
